pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount) public {
        // Ensure deposit amount is non-zero and within reasonable bounds
        vm.assume(depositAmount > 0 && depositAmount <= type(uint128).max);
        vm.assume(withdrawAmount > 0 && withdrawAmount <= depositAmount);

        // Deploy a single adversarial contract whose fallback reverts
        Reverter reverter = new Reverter();
        address attacker = address(reverter);

        // Fund the attacker with depositAmount
        vm.deal(attacker, depositAmount);

        // Attacker deposits some amount
        vm.prank(attacker);
        c.deposit{value: depositAmount}();

        // Record the initial balance of C
        uint256 balanceBefore = address(c).balance;

        // Ensure the attacker's credit is exactly depositAmount
        uint256 creditBefore = c.credit(attacker);
        assertEq(creditBefore, depositAmount);

        // Attacker attempts to withdraw the specified amount
        // Because the attacker is a Reverter, the low-level call will fail
        vm.prank(attacker);
        try c.withdrawAll() {
            // If withdrawAll succeeds, it shouldn't (reference would revert)
            // The invariant to check: balance reduction must match credit cleared
            uint256 creditAfter = c.credit(attacker);
            uint256 balanceAfter = address(c).balance;

            // Invariant: if withdrawAll did not revert, credit must be 0
            assertEq(creditAfter, 0);

            // Invariant: balance reduction equals credit cleared (which was depositAmount)
            assertEq(balanceBefore - balanceAfter, depositAmount);
        } catch {
            // If withdrawAll reverted (reference behavior), credit and balance must remain unchanged
            uint256 creditAfter = c.credit(attacker);
            uint256 balanceAfter = address(c).balance;

            assertEq(creditAfter, depositAmount);
            assertEq(balanceAfter, balanceBefore);
        }
    }
}

