        address donor = makeAddr("donor");
        vm.deal(donor, depositAmount);
        vm.prank(donor);
        c.deposit{value: depositAmount}();

        // attacker deposits too
        vm.deal(attacker, depositAmount + extraAmount);
        vm.prank(attacker);
        c.deposit{value: depositAmount}();

        uint256 totalCreditBefore = c.credit(attacker) + c.credit(donor);
        uint256 balanceBefore = address(c).balance + address(attacker).balance;

        // attacker withdraws – revert expected
