        vm.prank(attacker);
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        // Read current state
        uint256 totalCreditAfter = c.credit(attacker) + c.credit(donor);
        uint256 balanceAfter = address(c).balance + address(attacker).balance;

        // delta credit = delta ether for ALL parties (attacker, donor, c)
        assertTrue(ok && (totalCreditBefore - totalCreditAfter) == (balanceAfter - balanceBefore));
    }
