        try c.withdrawAll() { ok = true; } catch { ok = false; }
        uint256 balanceAfter = address(c).balance;
        // Property: if the call reverts, the internal balance and credit must remain unchanged;
        // if it succeeds, the actual ETH balance must not become less than internal balance.
        assertTrue(!ok || balanceAfter >= balanceBefore);
