pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawalAmount) public {
        // Bound to reasonable values to keep the search wide but practical
        depositAmount = bound(depositAmount, 1, 100 ether);
        withdrawalAmount = bound(withdrawalAmount, 1, depositAmount);

        // Prank the caller and deposit
        vm.deal(address(this), depositAmount);
        vm.prank(address(this));
        c.deposit{value: depositAmount}();

        // We need to withdraw a specific amount. Since withdrawAll takes no arguments and withdraws all, 
        // we must simulate a full withdrawal by first depositing and then calling withdrawAll. 
        // To test partial withdrawal, we would need a different function, but the bug is in withdrawAll.
        // So we just deposit and call withdrawAll. The fuzzer will vary the deposit amount.
        // Actually the function is withdrawAll with no parameters. Let's just fuzz the deposit amount 
        // and call withdrawAll. The property is about credit after successful withdrawal.

        vm.prank(address(this));
        c.withdrawAll();

        // After successful withdrawal, credit must be zero.
        // Since c.credit is private, there is no public getter. We need to check via balance or other means.
        // Actually, 'credit' is not declared public, but the compiler may generate a getter if it's public.
        // In the given code, 'mapping (address => uint) credit;' is NOT public, so c.credit(addr) is not accessible.
        // We have to infer credit indirectly. We can deposit again and see if credit accumulates incorrectly.
        // But the property must be a general rule that the reference satisfies and the bug breaks.
        // The reference sets credit to 0; the bug sets to 1. After a successful withdrawAll and then another deposit,
        // the credit should equal the new deposit if the original credit was 0. If the bug left 1, then credit 
        // would be deposit + 1. We can test by making another deposit and checking balance.
        // However, we don't have a getter for credit. The only way to infer credit is by balance changes 
        // or by total contract balance tracking.
        // Alternatively, we can call withdrawAll again. If credit is 1, a second withdrawAll would attempt to withdraw 1 wei,
        // causing a revert if balance is insufficient? That's possible but not guaranteed.
        // Wait: The original problem stated: "after a successful withdrawAll, the caller's credit mapping must be cleared to zero; the bug leaves it as 1."
        // But earlier attempts to use c.credit(actor) failed because it's not public. Fix: We must use a helper to observe credit indirectly?
        // No, the test is supposed to observe c's public surface. Since credit is private, we can't read it directly.
        // The property must be expressed in terms of public behavior.
        // What public behavior differs? The contract balance, or the ability to withdraw more than deposited?
        // If credit is not cleared, the user could withdraw again even though they already withdrew all.
        // So the invariant could be: After a successful withdrawAll, a subsequent withdrawAll should revert 
        // because credit should be zero. In the buggy version, the subsequent withdrawAll might succeed (stealing 1 wei).
        // Let's test that: call withdrawAll twice; the second call must revert on the reference, but may succeed on the bug.
        // That is a public behavior difference detectable via try/catch.

        // So we call withdrawAll a second time.
        bool secondWithdrawSucceeded;
        try c.withdrawAll() {
            secondWithdrawSucceeded = true;
        } catch {
            secondWithdrawSucceeded = false;
        }
        // On the reference, secondWithdrawSucceeded should be false (revert).
        // On the buggy, it might be true (since credit is 1, it tries to send 1 wei if balance >= 1).
        // But it depends on contract balance. After first withdrawal, contract balance is 0 (since we withdrew all).
        // The bug sets credit=1, so second withdrawAll would try balance -= oCredit where oCredit=1, 
        // but balance is 0, so underflow. In Solidity 0.8, underflow reverts. So it would revert anyway.
        // That doesn't work because balance=0 and oCredit=1 causes integer underflow revert.
        // So the second withdrawal would also revert, no difference.

        // We need to detect that the user can extract 1 wei more than they should. 
        // Approach: after first withdrawAll, deposit a small amount (e.g., 1 wei) so that balance >= 1. 
        // Then call withdrawAll again. If credit was 1 from before, total credit becomes 1 (old) + 1 (new) = 2. 
        // Then withdrawAll would try to withdraw 2, but balance is only 1, causing revert? No, balance is 1, 
        // and oCredit=2, so underflow when balance-=2 -> revert. So no difference.
        // If we deposit an amount that covers the stale credit, maybe we can detect by final balance.
        // Let's deposit 2 wei after first withdrawal. Then credit should be 2 (in reference) and 3 (in bug). 
        // Then withdrawAll: in reference, withdraws 2; in bug, withdraws 3. Contract balance in reference ends 0, 
        // in bug ends -1? No, underflow. So need balance >= credit. So deposit at least 3 wei in bug.
        // So if we deposit exactly 2, reference works, bug reverts; not a clean true/false invariant.
        // Better: After the first withdrawAll, the user should have no further claim on the contract. 
        // So if we then donate ether to the contract (not via deposit), the user should not be able to withdraw it. 
        // If credit is 1, they can withdraw 1 wei of donated funds.
        // Donate by sending directly (vm.deal to contract, or selfdestruct). We can vm.deal(address(c), 1 ether).
        // Then call withdrawAll. Reference: credit=0, oCredit=0, does nothing. Bug: credit=1, oCredit=1, attempts to withdraw 1 wei.
        // That succeeds because contract has 1 ether. So we can assert that after donating, withdrawAll reverts? Or we can check if any ether was sent.
        // Outcome: in reference, no ether transferred; in bug, 1 wei transferred. We can check our balance before and after.
        // That's a valid property: "After a successful full withdrawal, subsequent withdrawAll calls must not transfer any ether to the caller."
        // We can test by checking caller's balance difference after a withdrawAll following a donation.

        // However, we also need to handle that credit is not public. We can use balance change.
        // Let's simplify: After first withdrawAll, we donate 1 ether to c. Then we call withdrawAll. 
        // If our balance increases, the bug is triggered. On reference, our balance should not change.
        // So assert balance before == balance after (or at least no increase).
        // This works because withdrawAll only transfers if oCredit > 0. In reference, credit is 0, so no transfer. 
        // In bug, credit is 1, so transfer 1 wei.
        // This does not require reading credit directly.
    }
}

